---@class ActivityMidFestivalStoryTool
local ActivityMidFestivalStoryTool = {}

function ActivityMidFestivalStoryTool.PlotOverReq(questId)
    ---@type ActivityMidFestivalComponent
    local activityComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local activityId = activityComp:GetActivityDojo().id
    local reqData = {
        activityUuid = activityId,
        questId = questId
    }
    GameUtils.Request(Interfaces.OverseaMidFestivalPlot, reqData, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = jsonData.rewards
        if #rewards > 0 then
            GoodsUtils.DrawRewards(rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end
        activityComp:UpdateMainQuestId(jsonData.newMainQuestId)
        activityComp:UpdateRepaintQuestId(jsonData.unlockRepaintingQuestId)
        -- 重新刷新主线画面
        Events.Broadcast(Constants.EventNames.ActivityMidFestivalPlotPlayingOver)
    end)
end

return ActivityMidFestivalStoryTool
